def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if (r, c) in seen or grid[r][c] == background:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    markers = []
    for color, cells in components:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        height, width = r1 - r0 + 1, c1 - c0 + 1
        if height < 4 or width < 4 or len(cells) != height + width - 1:
            continue
        cellset = set(cells)
        for hr in (r0, r1):
            for vc in (c0, c1):
                expected = {(hr, c) for c in range(c0, c1 + 1)}
                expected.update((r, vc) for r in range(r0, r1 + 1))
                if cellset == expected:
                    markers.append((color, cells, hr, c0, c1))

    if not markers:
        return [row[:] for row in grid]

    marker_color, marker_cells, hr, c0, c1 = max(
        markers, key=lambda m: len(m[1])
    )

    targets = []
    for color, cells in components:
        if color == marker_color:
            continue
        minr = min(r for r, c in cells)
        minc = min(c for r, c in cells)
        maxc = max(c for r, c in cells)
        overlap = max(0, min(maxc, c1) - max(minc, c0) + 1)
        if minr > hr and overlap:
            targets.append((minr - hr, -overlap, cells))

    if not targets:
        return [row[:] for row in grid]

    target = min(targets, key=lambda x: (x[0], x[1]))[2]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = marker_color
    return out
